     1→ // @ts-nocheck
     2→// deno-lint-ignore-file no-explicit-any
     3→import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
     4→import DodoPayments from "https://esm.sh/dodopayments@2.4.1";
     5→
     6→const corsHeaders = {
     7→  "Access-Control-Allow-Origin": "*",
     8→  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, webhook-id, webhook-signature, webhook-timestamp",
     9→};
    10→
    11→Deno.serve(async (req) => {
    12→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
    13→
    14→  try {
    15→    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
    16→    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    17→    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
    18→    const WEBHOOK_KEY = Deno.env.get("DODO_PAYMENTS_WEBHOOK_KEY") || Deno.env.get("DODO_PAYMENTS_WEBHOOK_SECRET");
    19→
    20→    if (!DODO_API_KEY) {
    21→      console.error("DODO_PAYMENTS_API_KEY is not configured");
    22→      return new Response("Server misconfigured", { status: 500, headers: corsHeaders });
    23→    }
    24→    if (!WEBHOOK_KEY) {
    25→      console.error("DODO_PAYMENTS_WEBHOOK_KEY/SECRET is not configured");
    26→      return new Response("Server misconfigured", { status: 500, headers: corsHeaders });
    27→    }
    28→
    29→    const rawBody = await req.text();
    30→    const webhookHeaders = {
    31→      "webhook-id": req.headers.get("webhook-id") || "",
    32→      "webhook-signature": req.headers.get("webhook-signature") || "",
    33→      "webhook-timestamp": req.headers.get("webhook-timestamp") || "",
    34→    };
    35→
    36→    const dodo = new DodoPayments({
    37→      bearerToken: DODO_API_KEY,
    38→      webhookKey: WEBHOOK_KEY,
    39→    });
    40→
    41→    let unwrapped: any;
    42→    try {
    43→      unwrapped = dodo.webhooks.unwrap(rawBody, { headers: webhookHeaders });
    44→    } catch (e) {
    45→      console.error("Invalid webhook signature", e);
    46→      return new Response("Invalid signature", { status: 401, headers: corsHeaders });
    47→    }
    48→
    49→    const eventType: string = unwrapped.type || "unknown";
    50→    const payload: Record<string, unknown> = unwrapped.data || {};
    51→    const webhookId = webhookHeaders["webhook-id"];
    52→
    53→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
    54→
    55→    // Idempotency: skip if we've already processed this exact webhook-id
    56→    if (webhookId) {
    57→      const { data: dupList } = await supabase
    58→        .from("subscription_webhooks")
    59→        .select("id")
    60→        .eq("gateway", "dodo")
    61→        .eq("webhook_id", webhookId)
    62→        .limit(1);
    63→      if (dupList && dupList.length > 0) {
    64→        console.log(`Duplicate webhook ${webhookId}, skipping`);
    65→        return new Response("OK", { status: 200, headers: corsHeaders });
    66→      }
    67→    }
    68→
    69→    const subscriptionIdForLog = (payload["subscription_id"] as string | undefined) || null;
    70→
    71→    // Log the event (unprocessed)
    72→    const logInsert = await supabase
    73→      .from("subscription_webhooks")
    74→      .insert({
    75→        event_type: eventType,
    76→        payload: unwrapped,
    77→        gateway: "dodo",
    78→        processed: false,
    79→        dodo_subscription_id: subscriptionIdForLog,
    80→        webhook_id: webhookId || null,
    81→      })
    82→      .select("id")
    83→      .single();
    84→
    85→    const logId: string | null = logInsert.data?.id ?? null;
    86→
    87→    async function markProcessed(userId?: string | null) {
    88→      if (!logId) return;
    89→      await supabase
    90→        .from("subscription_webhooks")
    91→        .update({ processed: true, user_id: userId ?? null })
    92→        .eq("id", logId);
    93→    }
    94→
    95→    // Prefer correlation via metadata.local_payment_id (set at checkout creation)
    96→    const meta = (payload["metadata"] as Record<string, string> | undefined) || {};
    97→    const localPaymentId = (meta["local_payment_id"] as string | undefined) || null;
    98→
    99→    if (eventType === "payment.succeeded" || eventType === "payment_succeeded") {
   100→      const paymentId = (payload["payment_id"] as string | undefined) || null;
   101→
   102→      let paymentRow: any = null;
   103→      if (localPaymentId) {
   104→        const { data } = await supabase.from("payments").select("*").eq("id", localPaymentId).single();
   105→        paymentRow = data;
   106→      } else if (paymentId) {
   107→        const { data } = await supabase.from("payments").select("*").eq("dodo_payment_id", paymentId).single();
   108→        paymentRow = data;
   109→      }
   110→
   111→      if (paymentRow) {
   112→        // Persist Dodo payment id and mark as paid
   113→        if (paymentId && !paymentRow.dodo_payment_id) {
   114→          await supabase.from("payments").update({ dodo_payment_id: paymentId }).eq("id", paymentRow.id);
   115→        }
   116→        let newlyPaid = false;
   117→        if (paymentRow.status !== "paid") {
   118→          await supabase.from("payments").update({ status: "paid" }).eq("id", paymentRow.id);
   119→          newlyPaid = true;
   120→        }
   121→
   122→        if (newlyPaid) {
   123→          // Increment credits once (idempotent on status transition)
   124→          // Plan purchase → subscription_credits; pack purchase → topup_credits
   125→          const creditField = paymentRow.plan_id ? "subscription_credits" : "topup_credits";
   126→          const { data: profile } = await supabase
   127→            .from("profiles")
   128→            .select("credits, subscription_credits, topup_credits")
   129→            .eq("user_id", paymentRow.user_id)
   130→            .single();
   131→
   132→          if (profile) {
   133→            await supabase
   134→              .from("profiles")
   135→              .update({
   136→                [creditField]: ((profile as any)[creditField] ?? 0) + paymentRow.credits_purchased,
   137→                credits: (profile.credits ?? 0) + paymentRow.credits_purchased,
   138→              })
   139→              .eq("user_id", paymentRow.user_id);
   140→          }
   141→
   142→          // Activate plan if applicable
   143→          if (paymentRow.plan_id) {
   144→            const { data: plan } = await supabase
   145→              .from("plans")
   146→              .select("name, billing_type")
   147→              .eq("id", paymentRow.plan_id)
   148→              .single();
   149→
   150→            if (plan) {
   151→              const endsAt = new Date();
   152→              if (plan.billing_type === "yearly") {
   153→                endsAt.setFullYear(endsAt.getFullYear() + 1);
   154→              } else {
   155→                endsAt.setMonth(endsAt.getMonth() + 1);
   156→              }
   157→              await supabase
   158→                .from("profiles")
   159→                .update({
   160→                  plan: plan.name,
   161→                  subscription_ends_at: endsAt.toISOString(),
   162→                  dodo_subscription_id: (payload["subscription_id"] as string | undefined) || null,
   163→                })
   164→                .eq("user_id", paymentRow.user_id);
   165→            }
   166→          }
   167→        }
   168→
   169→        await markProcessed(paymentRow.user_id);
   170→      }
   171→    } else if (eventType === "payment.failed" || eventType === "payment_failed") {
   172→      const paymentId = (payload["payment_id"] as string | undefined) || null;
   173→      if (localPaymentId) {
   174→        await supabase
   175→          .from("payments")
   176→          .update({ status: "failed", dodo_payment_id: paymentId })
   177→          .eq("id", localPaymentId);
   178→      } else if (paymentId) {
   179→        await supabase.from("payments").update({ status: "failed" }).eq("dodo_payment_id", paymentId);
   180→      }
   181→      await markProcessed(null);
   182→    } else if (eventType === "subscription.renewed" || eventType === "subscription_renewed") {
   183→      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
   184→      if (subscriptionId) {
   185→        const { data: profile } = await supabase
   186→          .from("profiles")
   187→          .select("user_id, plan, credits, subscription_credits")
   188→          .eq("dodo_subscription_id", subscriptionId)
   189→          .single();
   190→
   191→        if (profile) {
   192→          const { data: plan } = await supabase
   193→            .from("plans")
   194→            .select("credits, billing_type")
   195→            .eq("name", profile.plan)
   196→            .single();
   197→
   198→          if (plan) {
   199→            const endsAt = new Date();
   200→            if (plan.billing_type === "yearly") {
   201→              endsAt.setFullYear(endsAt.getFullYear() + 1);
   202→            } else {
   203→              endsAt.setMonth(endsAt.getMonth() + 1);
   204→            }
   205→            await supabase
   206→              .from("profiles")
   207→              .update({
   208→                // Renewal always adds to subscription_credits (monthly allowance)
   209→                subscription_credits: ((profile as any).subscription_credits ?? 0) + plan.credits,
   210→                credits: (profile.credits ?? 0) + plan.credits,
   211→                subscription_ends_at: endsAt.toISOString(),
   212→              })
   213→              .eq("user_id", profile.user_id);
   214→          }
   215→        }
   216→      }
   217→      await markProcessed(null);
   218→    } else if (
   219→      eventType === "subscription.cancelled" ||
   220→      eventType === "subscription_cancelled" ||
   221→      eventType === "subscription.on_hold" ||
   222→      eventType === "subscription.failed"
   223→    ) {
   224→      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
   225→      if (subscriptionId) {
   226→        // For on_hold/failed: downgrade immediately; for cancelled, let expiry task handle downgrade.
   227→        if (eventType.includes("on_hold") || eventType.includes("failed")) {
   228→          await supabase
   229→            .from("profiles")
   230→            .update({
   231→              plan: "free",
   232→              dodo_subscription_id: null,
   233→              subscription_ends_at: null,
   234→            })
   235→            .eq("dodo_subscription_id", subscriptionId);
   236→        }
   237→      }
   238→      await markProcessed(null);
   239→    } else if (eventType === "subscription.active" || eventType === "subscription_active") {
   240→      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
   241→      if (subscriptionId && localPaymentId) {
   242→        const { data: payment } = await supabase.from("payments").select("user_id").eq("id", localPaymentId).single();
   243→        if (payment) {
   244→          await supabase.from("profiles").update({ dodo_subscription_id: subscriptionId }).eq("user_id", payment.user_id);
   245→          await markProcessed(payment.user_id);
   246→        }
   247→      }
   248→    }
   249→
   250→    return new Response("OK", { status: 200, headers: corsHeaders });
   251→  } catch (err) {
   252→    console.error("dodo-webhook error:", err);
   253→    return new Response("Internal error", { status: 500, headers: corsHeaders });
   254→  }
   255→});
